-- Fixed-scale approved art adapter. Arrays are generated by build_runtime.py.
local folder=debug.getinfo(1,"S").source:match("^@?(.*)[\\/][Ss]cripts[\\/]") or "."
local G={cache={}}
local function v(x,y,z)return {X=x,Y=y,Z=z}end
function G.build(lo,hi,config)
    assert(config.expected_long_axis=="X","Only the explicit X-forward calibration is supported")
    assert(type(lo.X)=="number" and type(hi.X)=="number" and
        hi.X-lo.X>300 and hi.X-lo.X<1500 and hi.Y-lo.Y>5 and hi.Z-lo.Z>5 and
        hi.X-lo.X>hi.Y-lo.Y and hi.X-lo.X>hi.Z-lo.Z,"Unexpected stock frame/bounds; calibration required")
    assert(config.uniform_scale>=.5 and config.uniform_scale<=1.5,"Uniform scale outside calibration limits")
    assert(config.yaw_degrees==0 or config.yaw_degrees==180,"Yaw must be 0 or 180 degrees for direction review")
    assert(config.lod==0 or config.lod==1 or config.lod==2,"Invalid LOD")
    local base=G.cache[config.lod]
    if not base then base=dofile(folder.."/Assets/LOD"..config.lod..".lua");G.cache[config.lod]=base end
    local center=config.align_stock_center and v((lo.X+hi.X)/2,(lo.Y+hi.Y)/2,(lo.Z+hi.Z)/2) or v(0,0,0)
    -- Identical paired/released tank bounds use identical immutable input arrays.
    -- Keep just the last transform: no unbounded per-actor geometry cache.
    local key=table.concat({config.lod,config.yaw_degrees,config.uniform_scale,center.X,center.Y,center.Z,config.offset_cm.X,config.offset_cm.Y,config.offset_cm.Z},"|")
    if G.lastKey==key then return G.lastMesh end
    local mesh={vertices={},normals={},uv=base.uv,tangents={},triangles=base.triangles,bodyTriangles=#base.triangles/3,pylonTriangles=0}
    local sign=config.yaw_degrees==180 and -1 or 1;local scale=config.uniform_scale;local offset=config.offset_cm
    for i,p in ipairs(base.vertices) do
        mesh.vertices[i]=v(center.X+offset.X+p.X*scale*sign,center.Y+offset.Y+p.Y*scale*sign,center.Z+offset.Z+p.Z*scale)
        local n=base.normals[i];mesh.normals[i]=v(n.X*sign,n.Y*sign,n.Z)
        local t=base.tangents[i];mesh.tangents[i]={TangentX=v(t.TangentX.X*sign,t.TangentX.Y*sign,t.TangentX.Z),bFlipTangentY=t.bFlipTangentY}
    end
    mesh.sections={}
    for index,part in ipairs(base.sections)do
        local section={vertices={},normals={},uv=part.uv,triangles=part.triangles,tangents={}}
        for i,p in ipairs(part.vertices)do
            section.vertices[i]=v(center.X+offset.X+p.X*scale*sign,center.Y+offset.Y+p.Y*scale*sign,center.Z+offset.Z+p.Z*scale)
            local n=part.normals[i];section.normals[i]=v(n.X*sign,n.Y*sign,n.Z)
            local t=part.tangents[i];section.tangents[i]={TangentX=v(t.TangentX.X*sign,t.TangentX.Y*sign,t.TangentX.Z),bFlipTangentY=t.bFlipTangentY}
        end
        mesh.sections[index]=section
    end
    G.lastKey,G.lastMesh=key,mesh
    return mesh
end
return G
